unsigned nx_action_count(void) { return sizeof(catalog) / sizeof(catalog[0]); }

const NxAction *nx_action(unsigned id) {
    return &catalog[id < nx_action_count() ? id : 0];
}

const NxAction *nx_action_for_vk(uint8_t vk) {
    for (unsigned i=0;i<nx_action_count();++i)
        if (catalog[i].vk==vk) return &catalog[i];
    return &catalog[0];
}
